// Scheme 1 only. The silver and orange renderers remain unchanged.
function uiIcon(name) {
  const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',chart:'M4 20V10h4v10M10 20V4h4v16M16 20v-8h4v8',file:'M6 3h8l4 4v14H6zM13 3v5h5M9 12h6M9 16h6',link:'M9 8H7a4 4 0 0 0 0 8h3M15 8h2a4 4 0 0 1 0 8h-3M8 12h8',check:'M5 12l4 4L19 6',arrow:'M5 12h14m-5-5 5 5-5 5',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',info:'M12 10v7M12 6v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
}
function blueBars(){
  const values=[32,47,38,58,67,51,74,62,89,70,57,77];
  return `<svg viewBox="0 0 660 236" class="b-chart" role="img" aria-label="8月各时段虚构线索数量，非实际分析结果"><defs><linearGradient id="b-bar" x1="0" y1="1" x2="0" y2="0"><stop stop-color="#1677ff"/><stop offset="1" stop-color="#9bcaff"/></linearGradient></defs><g stroke="#e9eff5"><path d="M40 30H645M40 75H645M40 120H645M40 165H645M40 200H645"/></g><g fill="#8996a6" font-size="12"><text x="12" y="34">100</text><text x="18" y="80">75</text><text x="18" y="124">50</text><text x="18" y="170">25</text></g>${values.map((v,i)=>`<rect x="${54+i*49}" y="${200-v*1.65}" width="18" height="${v*1.65}" rx="3" fill="url(#b-bar)"><title>时段 ${i+1}：${v} 条虚构线索</title></rect><rect x="${75+i*49}" y="${200-v*.78}" width="9" height="${v*.78}" rx="2" fill="#ffce73"/>`).join('')}<g fill="#8492a3" font-size="12"><text x="45" y="226">08.01</text><text x="191" y="226">08.08</text><text x="339" y="226">08.15</text><text x="487" y="226">08.22</text><text x="598" y="226">08.31</text></g></svg>`;
}
function blueHeroChart(){return `<svg viewBox="0 0 560 230" class="b-hero-chart" role="img" aria-label="示意图：社群、公域与问题线索相连接，不表示真实传播"><g stroke="#fff" opacity=".28" fill="none"><path d="M20 50H530M20 100H530M20 150H530M20 200H530M70 20V220M150 20V220M230 20V220M310 20V220M390 20V220M470 20V220"/><path d="M85 65L280 120L458 62M280 120L115 193M280 120L440 191" stroke-width="2"/></g><g fill="#fff" fill-opacity=".87"><rect x="22" y="40" width="125" height="48" rx="10"/><rect x="388" y="36" width="132" height="48" rx="10"/><rect x="35" y="166" width="160" height="48" rx="10"/><rect x="370" y="167" width="153" height="48" rx="10"/></g><g fill="#235584" font-size="15" text-anchor="middle"><text x="84" y="70">企微社群</text><text x="455" y="65">公域 VOC</text><text x="114" y="196">民间微信群</text><text x="447" y="197">人工核验</text></g><circle cx="280" cy="120" r="70" fill="#fff" opacity=".12"/><circle cx="280" cy="120" r="55" fill="#1677ff" stroke="#a9d7ff"/><text x="280" y="116" fill="#fff" text-anchor="middle" font-size="18">问题线索</text><text x="280" y="139" fill="#d8eeff" text-anchor="middle" font-size="12">SYNTHETIC DEMO</text></svg>`}
function blueDashboard(){
 const pending=examples.filter(c=>!confirmed.has(c.id));
 return `<section class="blue-v2"><aside class="b-sidebar"><a class="b-brand" href="#blue"><span class="b-logo">N</span>Ninebot<span class="b-brand-sub">Listening</span></a><nav aria-label="方案1页面导航"><button class="b-nav active" data-b-scroll="b-overview">${uiIcon('home')}总览</button><button class="b-nav" data-b-scroll="b-events">${uiIcon('file')}风险事件 <span>${pending.length}</span></button><button class="b-nav" data-b-scroll="b-analysis">${uiIcon('chart')}趋势分析</button><button class="b-nav" data-b-scroll="b-activity">${uiIcon('check')}核验动态</button></nav><div class="b-sidebar-bottom">${uiIcon('info')}<div>历史演示模式<small>仅虚构数据 · 不发送通知</small></div></div></aside><div class="b-main"><header class="b-toolbar"><label class="b-search">${uiIcon('search')}<input id="b-search" aria-label="搜索方案1事件" placeholder="搜索事件、问题类型或来源…"></label><div class="b-account"><span class="b-avatar">演</span><div>演示工作空间<small>Preview · 无需登录</small></div></div></header><div class="b-content" id="b-overview"><div class="b-title-row"><div><span class="b-kicker">DASHBOARD</span><h1>舆情总览</h1></div><span class="b-date">2026.08.01 — 08.31</span></div><section class="b-hero"><div class="b-hero-copy"><span class="b-kicker">NINEBOT / USER VOICES</span><h2>看见用户声音，<br>发现值得关注的问题。</h2><p>社群与公域线索汇总，<br>从原文证据进入人工核验。</p><button class="b-dark-button" data-b-scroll="b-events">查看风险事件 ${uiIcon('arrow')}</button></div><div class="b-hero-visual">${blueHeroChart()}</div><span class="b-hero-stamp">历史回放<small>虚构样品 / AUG 2026</small></span></section><div class="b-metrics">${[['示例分析内容','8,640','社群与公域合计','blue'],['待核验事件',pending.length,'需人工确认的示例','amber'],['已确认（模拟）',confirmed.size,'仅本页状态，刷新重置','green'],['优先核验',confirmed.has(1)?0:1,'安全相关表述','red']].map(([label,n,note,color])=>`<section class="b-card b-stat"><span>${label}</span><strong>${n}</strong><small class="b-${color}">${note}</small></section>`).join('')}</div><div class="b-middle"><section class="b-card" id="b-analysis"><div class="b-panel-head"><h2>问题线索趋势</h2><span class="b-tag">8 月 · 示意</span></div><div class="b-legend"><span><i></i>社群线索</span><span><i class="amber"></i>公域线索</span></div>${blueBars()}<p class="b-note">来源筛选口径不同，不直接比较负面率。</p></section><section class="b-card" id="b-activity"><div class="b-panel-head"><h2>核验动态</h2><button class="b-link" data-b-reset>重置演示</button></div><div class="b-activities">${(confirmed.size?[...confirmed].map(id=>examples.find(c=>c.id===id)):examples.slice(0,3)).map((c,i)=>`<button class="b-activity" data-open="${c.id}"><span class="b-activity-icon ${i===2?'amber':''}">${uiIcon(confirmed.has(c.id)?'check':'file')}</span><span><strong>${confirmed.has(c.id)?'已模拟确认':c.status} · ${c.name}</strong><small>${c.source} / ${confirmed.has(c.id)?'当前页面操作':'预置演示线索'}</small></span></button>`).join('')}</div><div class="b-context-note">${uiIcon('info')}独立评论无上下文，信息缺口保持未知。</div></section></div><section class="b-card b-events" id="b-events"><div class="b-panel-head"><h2>风险事件</h2><span class="b-tag">4 个虚构案例</span></div><div class="b-table-wrap"><table><thead><tr><th>事件与问题</th><th>来源渠道</th><th>核验状态</th><th>证据</th></tr></thead><tbody>${examples.map(c=>`<tr data-b-row data-search="${c.name} ${c.topic} ${c.source}"><td><button class="b-event-name" data-open="${c.id}"><span class="b-event-icon">${uiIcon('file')}</span><span>${c.name}<small>${c.topic} · 虚构示例</small></span></button></td><td>${c.source}</td><td><span class="b-pill ${confirmed.has(c.id)?'green':c.id===1?'red':'amber'}">${confirmed.has(c.id)?'已确认（模拟）':c.status}</span></td><td><button class="b-link" data-open="${c.id}">查看详情 ${uiIcon('arrow')}</button></td></tr>`).join('')}</tbody></table></div><p id="b-empty" class="b-empty" hidden>没有匹配的示例事件，请调整关键词。</p></section><footer class="b-footer">方案 01 · 按提供的 UI 参考重制 / 所有数值、事件与图表均为虚构，非模型分析结果。</footer></div></div></section>`;
}
blue=blueDashboard;
document.addEventListener('click',event=>{
 const target=event.target.closest('[data-b-scroll]');
 if(target){document.getElementById(target.dataset.bScroll)?.scrollIntoView({behavior:'smooth',block:'start'});document.querySelectorAll('.b-nav').forEach(n=>n.classList.toggle('active',n.dataset.bScroll===target.dataset.bScroll));}
 if(event.target.closest('[data-b-reset]')){confirmed.clear();render();}
});
document.addEventListener('input',event=>{
 if(event.target.id!=='b-search')return;
 const q=event.target.value.trim().toLowerCase();let found=0;
 document.querySelectorAll('[data-b-row]').forEach(row=>{row.hidden=!row.dataset.search.toLowerCase().includes(q);if(!row.hidden)found++;});
 document.getElementById('b-empty').hidden=found>0;
});
render();
